let req = null;
try { req = $('Tag POST').first().json; } catch (e) { req = null; }
if (!req) { try { req = $('Tag GET').first().json; } catch (e) { req = null; } }
req = req || { method: 'GET', token: '' };
const S = $('Get Settings').first().json.settings;
const esc = (x) => String(x).replace(/[&<>"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const biz = esc(s(S.business_name));
const token = s(req.token).replace(/[^a-zA-Z0-9]/g, '');
const customers = $('Read Customers').all().map(i => i.json);
const c = token ? customers.find(x => s(x.unsubscribe_token) === token) : null;
const page = (title, msg, form) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + '</title><style>body{font-family:system-ui,sans-serif;background:#f4f5f7;margin:0;display:flex;min-height:100vh;align-items:center;justify-content:center}.card{background:#fff;padding:32px;border-radius:12px;max-width:420px;box-shadow:0 2px 12px rgba(0,0,0,.08);text-align:center}button{background:#1E3A8A;color:#fff;border:0;padding:12px 24px;border-radius:8px;font-size:16px;cursor:pointer}h1{font-size:20px}p{color:#444}</style></head><body><div class="card"><h1>' + title + '</h1><p>' + msg + '</p>' + (form || '') + '</div></body></html>';
if (!c) return [{ json: { kind: 'SHOW', html: page('Link not valid', 'This unsubscribe link is not valid or has expired.') } }];
const done = page('You are unsubscribed', 'You will no longer receive reactivation emails from ' + biz + '.');
if (s(c.consent_status) === 'UNSUBSCRIBED') return [{ json: { kind: 'SHOW', html: done } }];
if (req.method !== 'POST') {
  const form = '<form method="POST" action="/webhook/unsubscribe?t=' + token + '"><button type="submit">Confirm unsubscribe</button></form>';
  return [{ json: { kind: 'SHOW', html: page('Unsubscribe', 'Click the button to stop receiving emails from ' + biz + '.', form) } }];
}
const now = nowIso();
return [{ json: { kind: 'DO', html: done,
  customerUpdate: { customer_id: s(c.customer_id), consent_status: 'UNSUBSCRIBED', campaign_status: 'STOPPED', stop_reason: 'UNSUBSCRIBED', updated_at: now },
  logRow: mkLog({ customer_id: s(c.customer_id), email: s(c.email), event_type: 'UNSUBSCRIBED', campaign_id: s(S.campaign_id), status: 'SUCCESS', metadata: 'Unsubscribed via link' }) } }];
